        # running; otherwise its aiohttp transport is finalized on another loop.
        await self._close_litellm_async_client()

@staticmethod
async def _close_litellm_async_client() -> None:
    """Close the shared litellm async HTTP client on the loop that created it."""
    client = getattr(litellm, "module_level_aclient", None)
    if client is None:
        return
    try:
        await client.close()
    except Exception:
        pass
    finally:
        # Drop the cached instance so the next call rebuilds it on the live loop
        # instead of reusing a client whose transport was just closed.
        try:
            delattr(litellm, "module_level_aclient")
        except Exception:
            pass

