import json
import time
import urllib.request


def probe():
    try:
        return urllib.request.urlopen("http://127.0.0.1:1933/health", timeout=5).status
    except Exception as exc:
        return str(exc)


print("before", probe())
body = json.dumps({"query": "aiohttp loop test query", "limit": 1}).encode()
request = urllib.request.Request(
    "http://127.0.0.1:1933/api/v1/search/find",
    data=body,
    headers={"Content-Type": "application/json"},
)
try:
    with urllib.request.urlopen(request, timeout=120) as response:
        payload = response.read(300).decode("utf-8", "replace")
        print("find status", response.status, payload[:200])
except Exception as exc:
    print("find error", exc)
time.sleep(10)
print("after", probe())
